        'tos.last_updated': { en: 'Last Updated: August 13, 2026', id: 'Terakhir Diperbarui: 13 Agustus 2026' },
        'tos.intro': { en: 'Welcome to NextBit. By accessing and using our website, you agree to comply with and be bound by the following Terms of Service.', id: 'Selamat datang di NextBit. Dengan mengakses dan menggunakan website kami, kamu setuju untuk mematuhi dan terikat oleh Syarat & Ketentuan berikut.' },

        'tos.s1': { en: '1. Introduction', id: '1. Pendahuluan' },
        'tos.s1p1': { en: 'Welcome to <strong>NextBit</strong>, also referred to as <strong>NextBit IT Solution</strong> ("NextBit," "we," "us," or "our").', id: 'Selamat datang di <strong>NextBit</strong>, juga disebut sebagai <strong>NextBit IT Solution</strong> ("NextBit," "kami," atau "milik kami").' },
        'tos.s1p2': { en: 'These Terms of Service ("Terms") govern your access to and use of the NextBit website, services, and products (collectively, the "Services").', id: 'Syarat & Ketentuan ("Ketentuan") ini mengatur akses dan penggunaanmu terhadap website, layanan, dan produk NextBit (secara kolektif, "Layanan").' },
        'tos.s1p3': { en: 'NextBit is a student-run freelance IT service based in <strong>Balikpapan, Indonesia</strong>. We provide IT support, computer and software setup, networking services, website development and design, and selected digital products.', id: 'NextBit adalah layanan IT freelance yang dikelola oleh pelajar yang berpusat di <strong>Balikpapan, Indonesia</strong>. Kami menyediakan dukungan IT, instalasi komputer dan software, layanan jaringan, pengembangan dan desain website, serta produk digital terpilih.' },
        'tos.s1p4': { en: 'By accessing our website, contacting us, purchasing a product, booking a service, or otherwise using our Services, you agree to these Terms. If you do not agree with these Terms, please do not use our Services.', id: 'Dengan mengakses website kami, menghubungi kami, membeli produk, memesan layanan, atau menggunakan Layanan kami, kamu menyetujui Ketentuan ini. Jika kamu tidak setuju dengan Ketentuan ini, mohon jangan gunakan Layanan kami.' },
        'tos.s1p5': { en: 'These Terms should be read together with our Privacy Policy and any separate agreement, quotation, invoice, or statement of work that applies to a particular service.', id: 'Ketentuan ini harus dibaca bersama dengan Kebijakan Privasi kami dan perjanjian, penawaran, invoice, atau ruang lingkup pekerjaan terpisah yang berlaku untuk layanan tertentu.' },

        'tos.s2': { en: '2. Our Services', id: '2. Layanan Kami' },
        'tos.s2p1': { en: 'NextBit may provide the following services:', id: 'NextBit dapat menyediakan layanan berikut:' },
        'tos.s2l1': { en: 'Computer and device setup and configuration', id: 'Instalasi dan konfigurasi komputer dan perangkat' },
        'tos.s2l2': { en: 'Windows installation and configuration', id: 'Instalasi dan konfigurasi Windows' },
