        'tos.s2l4': { en: 'Network installation, configuration, and troubleshooting', id: 'Instalasi, konfigurasi, dan perbaikan jaringan' },
        'tos.s2l5': { en: 'MikroTik and related network configuration', id: 'Konfigurasi MikroTik dan jaringan terkait' },
